chapters_21_to_30 = [
  {"chapter": "21", "title": "", "verses": ["እግዚአብሔርም እንደ ተናገረው ሣራን አሰበ፤ እግዚአብሔርም እንደ ተናገረው ለሣራ አደረገላት።", "ሣራም ፀነሰች፥ አብርሃምም በሸመገለበት ጊዜ እግዚአብሔር በተናገረው በዚያው ወራት ወንድ ልጅን ወለደችለት።", "አብርሃምም ሣራ ለወለደችለት ለልጁ ይስሐቅ ብሎ ስም አወጣለት።", "አብርሃምም ልጁን ይስሐቅን በስምንተኛው ቀን እግዚአብሔር እንዳዘዘው ገረዘው።", "አብርሃምም ልጁ ይስሐቅ በተወለደለት ጊዜ የመቶ ዓመት ሰው ነበረ።", "ሣራም አለች። እግዚአብሔር ሳቅ አደረገልኝ፤ ይህንም የሚሰማ ሁሉ በእኔ ምክንያት ይስቃል።", "ደግሞም። ሣራ ልጆችን እንድታጠባ ለአብርሃም ማን በነገረው? በሸመገለበት ጊዜ ልጅን ወልጄለታለሁና አለች።", "ሕፃኑም አደገ ጡትም ተወ፤ ይስሐቅም ጡት በተወበት ቀን አብርሃም ታላቅ ግብዣ አደረገ።", "ሣራም ግብፃዊቱ አጋር ለአብርሃም የወለደችለትን ልጅ ሲጫወት አየችው።", "አብርሃምንም አለችው። ይህችን ባሪያ ከልጅዋ ጋር አባራት፤ የዚች ባሪያ ልጅ ከልጄ ከይስሐቅ ጋር አይወርስምና።", "ይህም ነገር ስለ ልጁ በአብርሃም ዘንድ እጅግ ክፉ ሆነበት።", "እግዚአብሔርም አብርሃምን አለው። ስለ ብላቴናውና ስለ ባሪያህ ነገር አይክፋህ፤ ሣራ የምትነግርህን ቃል ሁሉ ስማ፤ በይስሐቅ ዘር ይጠራልሃልና።", "ደግሞም የባሪያይቱን ልጅ ዘርህ ስለ ሆነ ሕዝብ እንዲሆን አደርገዋለሁ።", "አብርሃምም በማለዳ ተነሣ፥ እንጀራንና የውኃ አቁማዳንም ወሰደ፥ ለአጋርም በጫንቃዋ ላይ አሸከማት፥ ሕፃኑንም ሰጥቶ አሰናበታት፤ እርስዋም ሄደች፥ በቤርሳቤህም ምድረ በዳ ተቅበዘበዘች።", "ውኃውም ከአቁማዳው አለቀ፤ ሕፃኑንም ከአንድ ቁጥቋጦ በታች ጣለችው።", "ሄዳም የሕፃኑን ሞት እንዳላይ ብላ የድንጋይ ውርወራ ያህል ርቃ በአንጻሩ ተቀመጠች። በአንጻሩም ተቀምጣ ድምፅዋን አንሥታ አለቀሰች።", "እግዚአብሔርም የብላቴናውን ድምፅ ሰማ፤ የእግዚአብሔርም መልአክ ከሰማይ አጋርን ጠርቶ አላት። አጋር ሆይ፥ ምን ሆነሻል? እግዚአብሔር የብላቴናውን ድምፅ ባለበት ስፍራ ሰምቶአልና አትፍሪ።", "ተነሺ፥ ብላቴናውን አንሺ፥ በእጅሽም ያዢው፤ ታላቅ ሕዝብ አደርገዋለሁና።", "እግዚአብሔርም ዓይኖችዋን ከፈተላት፥ የውኃ ጕድጓድንም አየች፤ ሄዳም አቁማዳውን በውኃ ሞላች፥ ብላቴናውንም አጠጣችው።", "እግዚአብሔርም ከብላቴናው ጋር ነበረ፥ አደገም፤ በምድረ በዳም ተቀመጠ፥ ቀስተactionም ሆነ።", "በፋራን ምድረ በዳም ተቀመጠ፤ እናቱም ከግብፅ ምድር ሚስት ወሰደችለት።", "በዚያም ወራት እንዲህ ሆነ፤ አቢሜሌክና የሠራዊቱ አለቃ ፊኮል አብርሃምን እንዲህ ብለው ተናገሩት። በምታደርገው ሁሉ እግዚአብሔር ከአንተ ጋር ነው፤", "አሁንም እኔንና ልጄን፥ የልጅ ልጄንም እንዳትበድል በዚህ በእግዚአብሔር ማልልኝ፤ እኔ ለአንተ እንዳደረግሁልህ በጎነት፥ እንግዳ ሆነህ ለተቀመጥህባት ምድርና ለእኔ እንዲሁ ታደርጋለህ።", "አብርሃምም። እኔ እምላለሁ አለ።", "አብርሃምም የአቢሜሌክ ባሪያዎች በግድ ስለ ወሰዱት ስለ ውኃው ጕድጓድ አቢሜሌክን ዘለፈው።", "አቢሜሌክም። ይህን ነገር ማን እንዳደረገው አላውቅም፥ አንተም አልነገርኸኝም፥ እኔም እስከ ዛሬ ድረስ አልሰማሁም አለ።", "አብርሃምም በጎችንና ላሞችን ወሰደ፥ ለአቢሜሌክም ሰጠ፤ ሁለቱም ቃል ኪዳን አደረጉ።", "አብርሃምም ከመንጋው ሰባት የሴቶች ጠቦቶችን ለብቻቸው አቆመ።", "አቢሜሌክም አብርሃምን። ለብቻቸው ያቆምሃቸው እነዚህ ሰባቱ ጠቦቶች ምንድር ናቸው? አለው።", "እርሱም። ይህችን የውኃ ጕድጓድ እኔ እንደ ማስሁ ለእኔ ምስክር እንዲሆኑ እነዚህን ሰባቱን ጠቦቶች ከእጄ ትወስዳለህ አለ።", "ስለዚህም ያንን ስፍራ ቤርሳቤህ ብሎ ጠራው፥ ሁለቱም በዚያ ምለዋልና።", "በቤርሳቤህም ቃል ኪዳን አደረጉ፤ አቢሜሌክና የሠራዊቱ አለቃ ፊኮልም ተነሡ፥ ወደ ፍልስጥኤምም ምድር ተመለሱ።", "አብርሃምም በቤርሳቤህ የባሕር ዛፍን ተከለ፤ በዚያም የዘላለም አምላክ የሆነውን የእግዚአብሔርን ስም ጠራ።", "አብርሃምም በፍልስጥኤም ምድር ብዙ ቀን ተቀመጠ።"]},
  {"chapter": "22", "title": "", "verses": ["ከዚህ ነገር በኋላ እንዲህ ሆነ፤ እግዚአብሔር አብርሃምን ፈተነው፥ እንዲህም አለው። አብርሃም፥ አብርሃም፤ እርሱም። እነሆኝ አለ።", "አለ። የምትወደውን አንድ ልጅህን ይስሐቅን ይዘህ ወደ ሞሪያም ምድር ሂድ፤ እኔም በሚነግርህ በአንድ ተራራ ላይ በዚያ መሥዋዕት አድርገህ ሠዋው።", "አብርሃምም በማለዳ ተነሣ፥ አህያውንም ጫነ፥ ከብላቴኖቹም ሁለት ከእርሱ ጋር ወሰደ ልጁንም ይስሐቅን፤ የመሥዋዕቱንም እንጨት ሰነጠቀ፥ ተነሥቶም እግዚአብሔር ወደ አለው ስፍራ ሄደ።", "በሦስተኛውም ቀን አብርሃም ዓይኑን አነሣ፥ ስፍራውንም ከሩቅ አየ።", "አብርሃምም ብላቴኖቹን። እናንተ ከአህያው ጋር በዚህ ቆዩ፥ እኔና ብላቴናው ግን ወደዚያ ሄደን እንሰግዳለን፥ ወደ እናንተም እንመለሳለን አላቸው።", "አብርሃምም የመሥዋዕቱን እንጨት ወስዶ ለልጁ ለይስሐቅ አሸከመው፥ እሳቱንና ቢላዋውንም በእጁ ያዘ፤ ሁለቱም አብረው ሄዱ።", "ይስሐቅም አባቱን አብርሃምን እንዲህ ብሎ ተናገረው። አባቴ ሆይ፤ እርሱም። እነሆኝ ልጄ አለ። እርሱም። እሳቱና እንጨቱ እነሆ፥ የመሥዋዕቱ በግ ወዴት አለ? አለ።", "አብርሃምም አለ። ልጄ ሆይ፥ የመሥዋዕቱን በግ እግዚአብሔር ለእርሱ ያዘጋጃል፤ ሁለቱም አብረው ሄዱ።", "እግዚአብሔር ወደ አለውም ስፍራ ደረሱ፤ አብርሃምም በዚያ መሠውያውን ሠራ፥ እንጨቱንም ረበረበ፤ ልጁን ይስሐቅንም አስሮ በመሠውያው በእንጨቱ ላይ አጋደመው።", "አብርሃምም እጁን ዘረጋ፥ ልጁንም ያርድ ዘንድ ቢላዋውን አነሣ።", "የእግዚአብሔር መልአክም ከሰማይ ጠራውና። አብርሃም፥ አብርሃም አለው፤ እርሱም። እነሆኝ አለ።", "እርሱም። በብላቴናው ላይ እጅህን አትዘርጋ፥ አንዳችም አታድርግበት፤ አንድ ልጅህን ለእኔ አልከለከልህምና እግዚአብሔርን የምትፈራ እንደ ሆንህ አሁን አውቄአለሁ አለ።", "አብርሃምም ዓይኑን አነሣና እነሆ፥ በስተ ኋላው አንድ በግ ቀንዶቹ በዕፅዋት ተይዞ አየ፤ አብርሃምም ሄደ በጉንም ወሰደ፥ በልጁም ፋንታ መሥዋዕት አድርጎ ሠዋው።", "አብርሃምም የዚያን ስፍራ ስም እግዚአብሔር ይዘጋጃል ብሎ ጠራው፤ እስከ ዛሬም ድረስ። በእግዚአብሔር ተራራ ይታያል ይባላል።", "የእግዚአብሔር መልአክም አብርሃምን ሁለተኛ ጊዜ ከሰማይ ጠራው፥", "እንዲህም አለው። በራሴ ማልሁ፥ ይላል እግዚአብሔር፥ ይህን ነገር አድርገሃልና፥ አንድ ልጅህንም አልከለከልህምና", "በእውነት በረከትን እባርክሃለሁ፥ ዘርህንም እንደ ሰማይ ከዋክብትና በባሕር ዳር እንዳለ አሸዋ እጅግ አበዛዋለሁ፤ ዘርህም የጠላቶችን ደጅ ይወርሳል፤", "የምድር አሕዛብ ሁሉም በዘርህ ይባረካሉ፥ ቃሌን ሰምተሃልና።", "አብርሃምም ወደ ብላቴኖቹ ተመለሰ፥ ተነሥተውም ወደ ቤርሳቤህ በአንድነት ሄዱ፤ አብርሃምም በቤርሳቤህ ተቀመጠ።", "ከዚህ ነገር በኋላ እንዲህ ሆነ፤ ለአብርሃም። እነሆ ሚልካ ለወንድምህ ለናኮር ደግሞ ልጆችን ወለደችለት ተብሎ ተነገረው፤", "የበኵር ልጁ ዑፅ ነው፥ ወንድሙ ቡዝ፥ የአራም አባት ቀሙኤል፥", "ካሣድ፥ ሐዞ፥ ፈልዳስ፥ ዬድላፍ፥ ባቱኤል።", "ባቱኤልም ርብቃን ወለደ፤ እነዚህን ስምንቱን ሚልካ ለአብርሃም ወንድም ለናኮር ወለደችለት።", "ቁባቱም ስምዋ ሬኡማ ነበረች፤ እርስዋም ደግሞ TabBar፥ ገሐም፥ ተሐሽ፥ መዓካን ወለደች።"]},
  {"chapter": "23", "title": "", "verses": ["የሣራም ዕድሜ መቶ ሀያ ሰባት ዓመት ሆነ፤ የሣራ ዕድሜ ዓመታት እነዚህ ናቸው።", "ሣራም በከነዓን ምድር በምትገኝ በኬብሮን በተባለች በአርባቅ ከተማ ሞተች፤ አብርሃምም ለሣራ ሊያለቅስላትና ሊያዝንላት ገባ።", "አብርሃምም ከሬሳው አጠገብ ተነሣ፥ ለኬጢ ልጆችም እንዲህ ብሎ ተናገረ።", "እኔ በእናንተ ዘንድ እንግዳና መጻተኛ ነኝ፤ ሬሳዬን ከፊቴ ሸሽጌ እቀብር ዘንድ በእናንተ ዘንድ የመቃብር ርስት ስጡኝ።", "የኬጢ ልጆችም ለአብርሃም መለሱ፥ አሉትም።", "ጌታችን ሆይ፥ ስማን፤ አንተ በእኛ መካከል የእግዚአብሔር አለቃ ነህ፤ ከእኛ በተመረጠው መቃብር ሬሳህን ቅበር፤ ሬሳህን እንዳትቀብር መቃብሩን የሚከለክልህ ከእኛ ማንም የለም።", "አብርሃምም ተነሣ፥ ለአገሩ ሰዎችም ለኬጢ ልጆች ሰገደ።", "እንዲህም ብሎ ተናገራቸው። ሬሳዬን ከፊቴ አርቄ እንድቀብር ፈቃዳችሁ እንደ ሆነ፥ ስሙኝ፥ ወደ ጾሐር ልጅ ወደ ኤፍሮንም ለምኑልኝ፤", "በእርሻው ዳርቻ ያለችውን የማክፈላ ዋሻውን እንዲሰጠኝ፤ ሬሳዬን የምቀብርበት ርስት ይሆነኝ ዘንድ በእናንተ መካከል በእውነተኛ ዋጋዋ ይስጠኝ።", "ኤፍሮንም በኬጢ ልጆች መካከል ተቀምጦ ነበር፤ ኬጢያዊውም ኤፍሮን በከተማው በር ለሚገቡት ለኬጢ ልጆች ሁሉ ፊት ለአብርሃም እንዲህ ሲል መለሰለት።", "ጌታዬ ሆይ፥ እንዲህ አይደለም፥ ስማኝ እንጂ፤ እርሻውን ለአንተ ሰጥቼሃለሁ፥ በእርሱም ውስጥ ያለችውን ዋሻ ለአንተ ሰጥቼሃለሁ፤ በወገኔ ልጆች ፊት ለአንተ ሰጥቼሃለሁ፤ ሬሳህን ቅበር።", "አብርሃምም በአገሩ ሰዎች ፊት ሰገደ።", "በአገሩም ሰዎች ፊት ኤፍሮንን እንዲህ ብሎ ተናገረው። ብትሰጠኝስ የእርሻውን ዋጋ እንድሰጥህ ስማኝ፤ ከእኔም ውሰደው፥ ሬሳዬንም በዚያ እቀብራለሁ።", "ኤፍሮንም ለአብርሃም እንዲህ ሲል መለሰለት።", "ጌታዬ ሆይ፥ ስማኝ፤ አራት መቶ ሰቅል ብር የሚያወጣ ምድር በእኔና በአንተ መካከል ምንድር ነው? እንግዲያስ ሬሳህን ቅበር።", "አብርሃምም የኤፍሮንን ነገር ሰማ፤ አብርሃምም ኤፍሮን በኬጢ ልጆች ፊት የተናገረውን በነጋዴዎች ዘንድ የሚሄደውን አራት መቶ ሰቅል ብር መዘነለት።", "በመምሬ ፊት በማክፈላ የነበረው የኤፍሮን እርሻና በእርሱ የነበረው ዋሻ በእርሻውም የነበረው በዳርቻውም ዙሪያ የነበረው ዛፍ ሁሉ፥", "በከተማው በር ለሚገቡት ለኬጢ ልጆች ሁሉ ፊት ለአብርሃም ርስት ሆነ።", "ከዚህም በኋላ አብርሃም ሚስቱን ሣራን በከነዓን ምድር በመምሬ ፊት ባለው በማክፈላ እርሻ ዋሻ ቀበራት፤ እርስዋም ኬብሮን ናት።", "እርሻውና በእርሱ የነበረው ዋሻ ለመቃብር ርስት እንዲሆን ከኬጢ ልጆች ለአብርሃም ጸናለት።"]},
  {"chapter": "24", "title": "", "verses": ["አብርሃምም በዕድሜው ሸምግሎ ፈጽሞ አርጅቶ ነበር፤ እግዚአብሔርም አብርሃምን በሁሉ ነገር ባርኮት ነበር።", "አብርሃምም በቤቱ ያለውን ከብቱን ሁሉ የሚገዛውን ታላቁን ባሪያውን አለው። እጅህን ከጭኔ በታች አድርግ፤", "እኔ በምቀመጥባቸው በከነዓናውያን ሴቶች ልጆች ለልጄ ሚስትን እንዳትወስድለት፥", "ነገር ግን ወደ አገሬና ወደ ዘመዶቼ ሄደህ ለልጄ ለይስሐቅ ሚስት እንድትወስድለት የሰማይ አምላክና የምድር አምላክ በሆነ በእግዚአብሔር አምልሃለሁ።", "ባሪያውም። ምናልባት ሴቲቱ ወደዚህች ምድር ልትከተለኝ ባትወድስ? ልጅህን ወደ ወጣህበት አገር ልመልሰውን? አለው።", "አብርሃምም አለው። ልጄን ወደዚያ እንዳትመልሰው ተጠንቀቅ።", "ከአባቴ ቤት ከተወለድሁበትም አገር ያወጣኝ እንዲህም ሲል የተናገረኝ። ይህችን ምድር ለአንተና ለዘርህ እሰጣለሁ ብሎ የማለልኝ የሰማይ አምላክ እግዚአብሔር፥ እርሱ መልአኩን በፊትህ ይሰድዳል፥ ከዚያም ለልጄ ሚስትን ትወስዳለህ።", "ሴቲቱ ግን ልትከተልህ ባትወድ ከዚህ መሐላዬ ንጹሕ ነህ፤ ብቻ ልጄን ወደዚያ አትመልሰው።", "ባሪያውም እጁን ከጌታው ከአብርሃም ጭን በታች አደረገ፥ ስለዚሁም ነገር ማለለት።", "ባሪያውም ከጌታው ግመሎች አሥር ግመሎችን ወሰደ፥ ከጌታውም ዕቃ ሁሉ መልካም መልካሙን በእጁ ይዞ ሄደ፤ ተነሥቶም ወደ ሁለቱ ወንዞች መካከል ምድር ወደ ናኮር ከተማ ደረሰ።", "በከተማይቱም ውጭ በውኃ ጕድጓድ አጠገብ ግመሎቹን አስበረከከ፤ ይህም ሴቶች ውኃ ሊቀዱ በሚወጡበት በማታ ጊዜ ነበረ።", "እንዲህም አለ። የጌታዬ የአብርሃም አምላክ እግዚአብሔር ሆይ፥ ዛሬ በመንገዴ አከናውነኝ፥ ለጌታዬ ለአብርሃምም ቸርነት አድርግ።", "እነሆ፥ እኔ በዚህ በውኃ ምንጭ አጠገብ እቆማለሁ፤ የዚህችም ከተማ ሰዎች ሴቶች ልጆች ውኃ ሊቀዱ ይወጣሉ።", "እንዲህም ይሁን፤ እኔ። እንድጠጣ እንስራሽን አዘንብዪ የምላት እርስዋም። ጠጣ ግመሎችህንም ደግሞ አጠጣለሁ የምትለኝ፥ እርስዋ ለባሪያህ ለይስሐቅ ያዘጋጀሃት ትሁን፤ በዚህም ለጌታዬ ቸርነት እንዳደረግህ አውቃለሁ።", "እንዲህም ሆነ፤ እርሱ መናገሩን ገና ሳይጨርስ እነሆ፥ ርብቃ እንስራዋን በጫንቃዋ ተሸክማ ወጣች፤ እርስዋም ለአብርሃም ወንድም ለናኮር ሚስት ለሚልካ ልጅ ለባቱኤል የተወለደች ነበረች።", "ብላቴናይቱም መልኳ እጅግ ያማረ ነበረ፥ ወንድ የማያውቃት ድንግልም ነበረች፤ ወደ ምንጩም ወረደች፥ እንስራዋንም ውኃ ሞላች፥ ወጣችም።", "ባሪያውም ሊቀበላት ሮጠ እንዲህም አለ። ከእንስራሽ ጥቂት ውኃ አጠጪኝ።", "እርስዋም። ጌታዬ ሆይ፥ ጠጣ አለች፤ ፈጥናም እንስራዋን በእጅዋ አወረደች፥ አጠጣችውም።", "እርሱን ማጠጣት ከፈጸመች በኋላ። ግመሎችህ እስኪጠግቡ ድረስ ደግሞ ውኃ እቀዳላቸዋለሁ አለች።", "ፈጥናም የእንስራዋን ውኃ በገንዳው ውስጥ አፈሰሰች፥ እንደ ገናም ውኃ ልትቀዳ ወደ ጉድጓዱ ሮጠች፥ ለግመሎቹም ሁሉ ቀዳች።", "ሰውዬውም እግዚአብሔር መንገዱን አከናውኖለት እንደ ሆነ ወይም እንዳልሆነ ያውቅ ዘንድ ዝም ብሎ ይመለከታት ነበር።", "ግመሎቹም መጠጣትን በፈጸሙ ጊዜ ሰውዬው ግማሽ ሰቅል የሚመዝን የወርቅ ጉትቻ ወሰደ፥ በእጆችዋም የሚሆኑ አሥር ሰቅል ወርቅ የሚመዝኑ ሁለት አምባሮችን ወሰደላት፤", "እንዲህም አላት። አንቺ የማን ልጅ ነሽ? ንገሪኝ፤ በአባትሽ ቤት የምናድርበት ስፍራ አለን?", "እርስዋም። እኔ ሚልካ ለናኮር የወለደችለት የባቱኤል ልጅ ነኝ አለችው።", "ደግሞም። ገለባና ብዙ ገፈራ አለን፥ የምታድሩበትም ስፍራ አለን አለችው።", "ሰውዬውም አጎነበሰ፥ ለእግዚአብሔርም ሰገደ፥", "እንዲህም አለ። ለጌታዬ ለአብርሃም ቸርነቱንና እውነቱን ያልተወ የጌታዬ የአብርሃም አምላክ እግዚአብሔር ይመስገን፤ እኔ በመንገድ ሳለሁ እግዚአብሔር ወደ ጌታዬ ወንድሞች ቤት መራኝ።", "ብላቴናይቱም ሮጣ ይህን ነገር ሁሉ ለእናቷ ቤተ ሰዎች አወራች።", "ለርብቃም ላባ የሚባል ወንድም ነበራት፤ ላባም ወደ ሰውዬው ወደ ምንጩ ወደ ውጭ ሮጠ።", "ጉትቻውንና በእኅቱ እጅ ያሉትን አምባሮች ባየ ጊዜ፥ እኅቱም ርብቃ። ሰውዬው እንዲህ አለኝ ብላ የተናገረችውን በሰማ ጊዜ ወደ ሰውዬው መጣ፤ እነሆም በምንጩ አጠገብ በግመሎቹ አጠገብ ቆሞ ነበር።", "አለውም። አንተ የእግዚአብሔር ቡሩክ፥ ግባ፤ በውጭ ለምን ትቆማለህ? እኔ ቤቱንና ለግመሎች የሚሆን ስፍራ አዘጋጅቼአለሁ።", "ሰውዬውም ወደ ቤት ገባ፤ ግመሎቹንም ፈታ፥ ለግመሎቹም ገለባና ገፈራ፥ ለእርሱ እግርና ከእርሱ ጋር ላሉት ሰዎች እግር መታጠቢያ ውኃ ሰጠ።", "በፊቱም መብል አቀረበለት፤ እርሱ ግን። ነገሬን እስክናገር ድረስ አልበላም አለ። እርሱም። ተናገር አለው።", "እንዲህም አለ። እኔ የአብርሃም ባሪያ ነኝ።", "እግዚአብሔርም ጌታዬን እጅግ ባረከው፥ ከበረም፤ በጎችንና ላሞችን ብርንም ወርቅንም ወንዶችና ሴቶች ባሪያዎችንም ግመሎችንና አህዮችንም ሰጠው።", "የጌታዬ ሚስት ሣራም ከሸመገለች በኋላ ለጌታዬ ወንድ ልጅ ወለደችለት፤ ያለውንም ሁሉ ለእርሱ ሰጠው።", "ጌታዬም እንዲህ ብሎ አማለኝ። እኔ ከተቀመጥሁበት ከአገራቸው ከከነዓናውያን ሴቶች ልጆች ለልጄ ሚስት አትውሰድለት፤", "ነገር ግን ወደ አባቴ ቤት ወደ ዘመዶቼም ሂድ፥ ለልጄም ሚስትን ውሰድለት።", "እኔም ጌታዬን። ምናልባት ሴቲቱ ባትከተለኝስ? አልሁት።", "እርሱም አለኝ። አካሄዴን በፊቱ ያደረግሁ እግዚአብሔር መልአኩን ከአንተ ጋር ይሰድዳል፥ መንገድህንም ያቀናልሃል፥ ለልጄም ከዘመዶቼ ከአባቴም ቤት ሚስትን ትወስዳለህ፤", "ወደ ዘመዶቼ በደረስህ ጊዜ ከመሐላዬ ንጹሕ ትሆናለህ፤ ባይሰጡህም ከመሐላዬ ንጹሕ ትሆናለህ።", "ዛሬም ወደ ውኃው ምንጭ ደረስሁ፥ አልሁም። የጌታዬ የአብርሃም አምላክ እግዚአብሔር ሆይ፥ የምሄድበትን መንገዴን አሁን ብታቀናልኝ፥", "እነሆ፥ እኔ በዚህ በውኃ ምንጭ አጠገብ እቆማለሁ፤ እንዲህም ይሁን፤ ውኃ ልትቀዳ የምትወጣይቱ ቆንጆ። ከእንስራሽ ጥቂት ውኃ አጠጪኝ የምላት፥", "እርስዋም። አንተም ጠጣ ለግመሎችህም ደግሞ እቀዳለሁ የምትለኝ፥ እርስዋ እግዚአብሔር ለጌታዬ ልጅ ያዘጋጃት ሚስት ትሁን።", "ይህንንም በልቤ መናገር ሳልፈጽም፥ እነሆ፥ ርብቃ እንስራዋን በጫንቃዋ ተሸክማ ወጣች፤ ወደ ምንጩም ወረደች ውኃም ቀዳች፤ እኔም። ውኃ አጠጪኝ አልኋት።", "ፈጥናም እንስራዋን ከጫንቃዋ አወረደችና። ጠጣ፥ ግመሎችህንም ደግሞ አጠጣለሁ አለች፤ ጠጣሁም ግመሎቼንም ደግሞ አጠጣች።", "ጠየቅኋትም። የአንቺ ልጅ ነሽ? አልኋት፤ እርስዋም። ሚልካ ለናኮር የወለደችለት የባቱኤል ልጅ ነኝ አለች። ጉትቻውንም በአፍንጫዋ፥ አምባሮቹንም በእጆችዋ አደረግሁላት።", "አጎነበስሁም፥ ለእግዚአብሔርም ሰገድሁ፥ የጌታዬን የወንድሙን ልጅ ለልጁ እወስድ ዘንድ በእውነተኛ መንገድ የመራኝን የጌታዬን የአብርሃምን አምላክ እግዚአብሔርን አመሰገንሁ።", "አሁንም ለጌታዬ ቸርነትንና እውነትን የምታደርጉ እንደ ሆናችሁ ንገሩኝ፤ ባይሆንም ወደ ቀኝ ወይም ወደ ግራ ዘወር እንድል ንገሩኝ።", "ላባና ባቱኤልም እንዲህ ብለው መለሱ። ነገሩ ከእግዚአብሔር ዘንድ ወጥቶአል፤ ክፉ ወይም በጎ ልንነግርህ አንችልም።", "እነሆ፥ ርብቃ በፊትህ ናት፤ ውሰዳትና ሂድ፤ እግዚአብሔር እንደ ተናገረ ለጌታህ ልጅ ሚስት ትሁን።", "የአብርሃምም ባሪያ ነገራቸውን በሰማ ጊዜ ወደ ምድር ተደፍቶ ለእግዚአብሔር ሰገደ።", "ባሪያውም የብርና የወርቅ ጌጥ ልብስም አወጣ፥ ለርብቃም ሰጣት፤ ለወንድምዋና ለእናትዋም የከበረ ስጦታን ሰጠ።", "እርሱና ከእርሱ ጋር የነበሩት ሰዎች በሉ፥ ጠጡም፥ በዚያም አደሩ፤ በማለዳም ተነሥተው። ወደ ጌታዬ አሰናብቱኝ አለ።", "የብላቴናይቱ ወንድምና እናትዋም። ብላቴናይቱ አሥር ቀን ያህል ከእኛ ጋር ትቀመጥ፤ ከዚያ በኋላ ትሄዳለች አሉ።", "እርሱ ግን። እግዚአብሔር መንገዴን ካቀናልኝ አታዘግዩኝ፤ ወደ ጌታዬ እሄድ ዘንድ አሰናብቱኝ አላቸው።", "እነርሱም። ብላቴናይቱን እንጥራትና አፍዋን እንጠይቃት አሉ።", "ርብቃንም ጠርተው። ከዚህ ሰው ጋር ትሄጃለሽን? አሏት፤ እርስዋም። እሄዳለሁ አለች።", "እኅታቸውን ርብቃንና ሞግዚቷን የአብርሃምንም ባሪያ ሰዎቹንም አሰናበቱ።", "ርብቃንም መረቋት እንዲህም አሉአት። አንቺ እኅታችን፥ የእልፍ አእላፋት እናት ሁኚ፤ ዘርሽም የጠላቶችን ደጅ ይውረስ።", "ርብቃና ደንገturዎቿም ተነሡ፥ በግመሎችም ላይ ተቀምጠው ሰውዬውን ተከተሉት፤ ባሪያውም ርብቃን ይዞ ሄደ።", "ይስሐቅም በብኤርለሃይሮኢ መንገድ መጣ፤ በአዜብ ምድር ተቀምጦ ነበርና።", "ይስሐቅም በመሸ ጊዜ ወደ ሜዳ ሊጸልይ ወጣ፤ ዓይኑንም አነሣና እነሆ ግመሎች ሲመጡ አየ።", "ርብቃም ዓይንዋን አነሣች፥ ይስሐቅንም አየች፥ ከግመልም ወረደች።", "ባሪያውንም። በሜዳ እኛን ሊቀበል የሚመጣው ያ ሰው ማን ነው? አለችው። ባሪያውም። እርሱ ጌታዬ ነው አላት፤ መሸፈኛዋን ወስዳ ተሸፈነች።", "ባሪያውም ያደረገውን ነገር ሁሉ ለይስሐቅ ነገረው።", "ይስሐቅም ወደ እናቱ ወደ ሣራ ድንኳን አገባት፥ ርብቃንም ወሰዳት ሚስትም ሆነችው፥ ወደዳትም፤ ይስሐቅም ከእናቱ ሞት ተጽናና። a"]},
  {"chapter": "25", "title": "", "verses": ["አብርሃምም ደግሞ ኬጡራ የምትባል ሚስት አገባ።", "እርስዋም ዜምራንን፥ ዮቅሳንንም፥ ሜዳንንም፥ ምድያምንም፥ የስቦቅንም፥ ስዌሕንም ወለደችለት።", "ዮቅሳንም ሳባንና ድዳንን ወለደ። የድዳንም ልጆች አሦራውያንና ላጡሳውያን፥ ላኦማውያን ናቸው።", "የምድያምም ልጆች ጌፌር፥ ዔፌር፥ ሄኖክ፥ አቢዳዕ፥ ኤልዳዓ ናቸው፤ እነዚህ ሁሉ የኬጡራ ልጆች ናቸው።", "አብርሃምም ያለውን ሁሉ ለይስሐቅ ሰጠው።", "ለአብርሃም ግን ለነበሩት ለቁባቶቹ ልጆች አብርሃም ስጦታን ሰጣቸው፤ እርሱም ገና በሕይወቱ ሳለ ከልጁ ከይስሐቅ ለይቶ ወደ ምሥራቅ አገር ሰደዳቸው።", "አብርሃምም የኖረበት የዕድሜው ዘመን ይህ ነው፤ መቶ ሰባ አምስት ዓመት ኖረ።", "አብርሃምም ነፍሱን ሰጠ በመልካም ሽምግልናም ሞተ፥ ዕድሜ ጠግቦ አረጀ፥ ወደ ወገኖቹም ተሰበሰበ።", "ልጆቹ ይስሐቅና እስማኤልም በመምሬ ፊት ለፊት ባለው በኬጢያዊ በጾሐር ልጅ በኤፍሮን እርሻ በማክፈላ ዋሻ ቀበሩት፤", "ይህም አብርሃም ከኬጢ ልጆች የገዛው እርሻ ነው፤ በዚያ አብርሃምና ሚስቱ ሣራ ተቀበሩ።", "ከአብርሃምም ሞት በኋላ እግዚአብሔር ልጁን ይስሐቅን ባረከው፤ ይስሐቅም በብኤርለሃይሮኢ አጠገብ ተቀመጠ።", "የሣራ ባሪያ ግብፃዊቱ አጋር ለአብርሃም የወለደችለት የአብርሃም ልጅ የእስማኤል ትውልድ ይህ ነው።", "እንደየስማቸውና እንደየነገዳቸው የእስማኤል ልጆች ስም ይህ ነው፤ የእስማኤል የበኵር ልጁ ነባዮት፥ ቄዳርም፥ አድብኤልም፥ ሚብሳምም፥", "ሚስማዕም፥ ዱማም፥ ማሣም፥", "ሃዳድም፥ ቴማም፥ ዬጡርም፥ ናፌስም፥ ቄድማም።", "የእስማኤል ልጆች እነዚህ ናቸው፤ በየመንደራቸውና በየሰፈራቸው ስማቸው ይህ ነው፤ በየአሕዛባቸው አሥራ ሁለት አለቆች ናቸው።", "የእስማኤልም ዕድሜ ዘመን መቶ ሠላሳ ሰባት ዓመት ነው፤ ነፍሱንም ሰጠ፥ ሞተም፥ ወደ ወገኖቹም ተሰበሰበ።", "አገራቸውም ከኤውላጥ ጀምሮ በግብፅ ፊት ለፊት እስካለችው ወደ አሦር በምትወስደው እስከ ሱር ድረስ ነው፤ በወንድሞቹ ሁሉ ፊት ተቀመጠ።", "የአብርሃም ልጅ የይስሐቅ ትውልድ ይህ ነው፤ አብርሃም ይስሐቅን ወለደ፤", "ይስሐቅም የሁለቱ ወንዞች መካከል ምድር ሰው የሆነውን የሶርያዊውን የባቱኤልን ልጅ የሶርያዊውን የላባን እኅት ርብቃን ባገባ ጊዜ የአርባ ዓመት ሰው ነበረ።", "ይስሐቅም ሚስቱ መካን ነበረችና ስለ እርስዋ ወደ እግዚአብሔር ጸለየ፤ እግዚአብሔርም ተለመነው፥ ሚስቱ ርብቃም ፀነሰች።", "ልጆቹም በሆድዋ ውስጥ ይጋፉ ነበር፤ እርስዋም። እንዲህ ከሆነ ለምን እንዲህ እሆናለሁ? አለች፤ እግዚአብሔርንም ለመጠየቅ ሄደች።", "እግዚአብሔርም አላት። ሁለት ወገኖች በማኅፀንሽ አሉ፥ ሁለቱም ሕዝቦች ከሆድሽ ይከፈላሉ፤ አንዱ ሕዝብ ከሁለተኛው ሕዝብ ይበረታል፥ ታላቁም ለታናሹ ይገዛል።", "የመውለጃዋም ወራት በተፈጸመ ጊዜ፥ እነሆ፥ በማኅፀንዋ መንታ ልጆች ነበሩ።", "የመጀመሪያውም ወጣ፥ እርሱም ቀይ ነበረ፥ ሁለንተናውም እንደ ጠጉር ልብስ ነበረ፤ ስሙንም ዔሳው ብለው ጠሩት።", "ከዚህም በኋላ ወንድሙ ወጣ፥ እጁም የዔሳውን ተረከዝ ይዞ ነበር፤ ስሙም ያዕቆብ ተባለ፤ ርብቃም በወለደቻቸው ጊዜ ይስሐቅ የስድሳ ዓመት ሰው ነበረ።", "ብላቴኖቹም አደጉ፤ ዔሳውም አደን የሚያውቅ የበረሀ ሰው ሆነ፤ ያዕቆብ ግን በድንኳን የሚቀመጥ ጭምት ሰው ነበረ።", "ይስሐቅም ዔሳውን ወደደ፥ ከአደኑ ይበላ ነበርና፤ ርብቃ ግን ያዕቆብን ወደደችው።", "ያዕቆብም ምስር ቀቀለ፤ ዔሳውም ደክሞት ከበረሀ መጣ።", "ዔሳውም ያዕቆብን። እኔ ደክሜአለሁና ከዚህ ከቀዩ ወጥ አብላኝ አለው፤ ስለዚህም ስሙ ኤዶም ተባለ።", "ያዕቆብም። መጀመሪያ የብኵርናህን መብት ሽጥልኝ አለው።", "ዔሳውም። እነሆ፥ እኔ ልሞት ነኝ፤ ይህች ብኵርና ለእኔ ምን ትጠቅመኛለች? አለ።", "ያዕቆብም። መጀመሪያ ማልልኝ አለው፤ ማለለትም፥ ብኵርናውንም ለያዕቆብ ሻጠ።", "ያዕቆብም ለዔሳው እንጀራና የምስር ወጥ ሰጠው፤ በላ፥ ጠጣም፥ ተነሥቶም ሄደ፤ እንዲሁም ዔሳው ብኵርናውን አቃለላት።"]},
  {"chapter": "26", "title": "", "verses": ["በአብርሃምም ዘመን ከነበረው የመጀመሪያው ራብ ሌላ በምድር ላይ ራብ ሆነ፤ ይስሐቅም ወደ ፍልስጥኤም ንጉሥ ወደ አቢሜሌክ ወደ ጌራራ ሄደ።", "እግዚአብሔርም ተገለጠለት እንዲህም አለው። ወደ ግብፅ አትውረድ፤ እኔ በምነግርህ ምድር ተቀመጥ እንጂ።", "በዚች ምድር ተቀመጥ፥ ከአንተ ጋርም እሆናለሁ፥ እባርክሃለሁም፤ እነዚህን ምድሮች ሁሉ ለአንተም ለዘርህም እሰጣለሁና፥ ለአባትህ ለአብርሃም የማልሁለትንም መሐላ አጸናለሁ፤", "ዘርህንም እንደ ሰማይ ከዋክብት አበዛለሁ፥ እነዚህንም ምድሮች ሁሉ ለዘርህ እሰጣለሁ፤ የምድር አሕዛብ ሁሉም በዘርህ ይባረካሉ፤", "አብርሃም ቃሌን ሰምቶአልና፥ ትእዛዜንና ሕጌን ሥርዓቴንም ጠብቆአልና።", "ይስሐቅም በጌራራ ተቀመጠ።", "የዚያ ስፍራ ሰዎችም ስለ ሚስቱ ጠየቁት እርሱም። እኅቴ ናት አለ፤ ርብቃ መልከ መልካም ነበረችና። የዚያ ስፍራ ሰዎች ስለ ርብቃ እንዳይገድሉኝ ብሎ ሚስቴ ናት ለማለት ፈርቶ ነበርና።", "በዚያም ብዙ ቀን ከተቀመጠ በኋላ የፍልስጥኤም ንጉሥ አቢሜሌክ በመስኮት ተመለከተ፥ እነሆም፥ ይስሐቅ ከሚስቱ ከርብቃ ጋር ሲጫወት አየ።", "አቢሜሌክም ይስሐቅን ጠርቶ። በእውነት እርስዋ ሚስትህ ናት፤ አንተስ። እኅቴ ናት እንዴት አልህ? አለው፤ ይስሐቅም። በእርስዋ ምክንያት እንዳልሞት ብዬ ነው አለው።", "አቢሜሌክም። ይህ ያደረግህብን ምንድር ነው? ከሕዝቡ አንዱ ከሚስትህ ጋር ተኝቶ ቢሆን ኖሮ በላያችን በደልን ባመጣህብን ነበር አለ።", "አቢሜሌክም ሕዝቡን ሁሉ እንዲህ ብሎ አዘዘ። ይህን ሰው ወይም ሚስቱን የሚነካ ፈጽሞ ይገደላል።", "ይስሐቅም በዚያች ምድር ዘረ፥ በዚያችም ዓመት መቶ እጥፍ አገኘ፤ እግዚአብሔርም ባረከው።", "ሰውዬውም ከበረ፥ እጅግም እስኪበለጥግ ድረስ እየጨመረ ይሄድ ነበር፤", "የበግና የላም መንጋዎችም ነበሩት፥ ብዙዎች ባሪያዎችም ነበሩት፤ ፍልስጥኤማውያንም ቀኑበት።", "በአባቱ በአብርሃም ዘመን የአባቱ ባሪያዎች የማሱአቸውን የውኃ ጕድጓዶች ሁሉ ፍልስጥኤማውያን አፈረሱአቸው፥ አፈርም ሞሉባቸው።", "አቢሜሌክም ይስሐቅን። ከአኛ ይልቅ እጅግ በርትተሃልና ከእኛ ዘንድ ሂድ አለው።", "ይስሐቅም ከዚያ ሄደ፥ በጌራራም ሸለቆ ሰፈረ፥ በዚያም ተቀመጠ።", "ይስሐቅም በአባቱ በአብርሃም ዘመን ምሰውት የነበረውን፥ አብርሃም ከሞተ በኋላ ፍልስጥኤማውያን የደፈኑትን፥ የውኃውን ጕድጓድ ዳግመኛ ማሰ፤ አባቱም ያወጣላቸውን ስም አወጣላቸው።", "የይስሐቅም ባሪያዎች በሸለቆው ውስጥ ማሱ፥ የጣፋጭ ውኃም ምንጭ አገኙ።", "የጌራራ እረኞችም። ውኃው የእኛ ነው ብለው ከይስሐቅ እረኞች ጋር ተጣሉ፤ የዚያንም ጕድጓድ ስም ኤሴቅ ብሎ ጠራው፥ ከእርሱ ጋር ስለ ተጣሉ።", "ሌላም ጉድጓድ ማሱ፥ ስለ እርሱም ደግሞ ተጣሉ፤ ስሙንም ሲጥና ብሎ ጠራው።", "ከዚያም ፈቀቅ አለ፥ ሌላም ጕድጓድ ማሰ፥ ስለ እርሱም አልተጣሉም፤ ስሙንም። አሁን እግዚአብሔር አሰፋልን፥ በምድርም እናፈራለን ሲል 進行 (ረሆቦት) አለው።", "ከዚያም ወደ ቤርሳቤህ ወጣ።", "እግዚአብሔርም በዚያች ሌሊት ተገለጠለት፥ እንዲህም አለው። እኔ የአባትህ የአብርሃም አምላክ ነኝ፤ አትፍራ፥ እኔ ከአንተ ጋር ነኝና፥ እባርክሃለሁም፥ ዘርህንም ስለ ባሪያዬ ስለ አብርሃም አበዛለሁ።", "በዚያም መሠውያውን ሠራ፥ የእግዚአብሔርንም ስም ጠራ፥ ድንኳኑንም በዚያ ተከለ፤ የይስሐቅም ባሪያዎች በዚያ ጕድጓድ ማሱ።", "አቢሜሌክም ከሚዜው ከአሑዛትና ከሠራዊቱ አለቃ ከፊኮል ጋር ከጌራራ ወደ እርሱ መጣ።", "ይስሐቅም። እናንተ ጠልታችሁኛል፥ ከእናንተም ዘንድ አሳድዳችሁኛል፤ ወደ እኔ ስለ ምን መጣችሁ? አላቸው።", "እነርሱም አሉ። እግዚአብሔር ከአንተ ጋር እንደ ሆነ በእውነት አየን፤ እኛም። በእኛና በአንተ መካከል መሐላ ይሁን አልን፥ ከአንተም ጋር ቃል ኪዳን እናደርጋለን፤", "እኛ እንዳልነካንህ፥ መልካምም ብቻ እንዳደረግንልህ፥ በሰላምም እንደ ሰደድንህ፥ አንተ ደግሞ ክፉ እንዳታደርግብን፤ አንተ አሁን የእግዚአብሔር ቡሩክ ነህ።", "ግብዣም አደረገላቸው፥ በሉም ጠጡም።", "በማለዳም ተነሡ፥ እርስ በርሳቸውም ተማማሉ፤ ይስሐቅም አሰናበታቸው፥ ከእርሱም በሰላም ሄዱ።", "በዚያም ቀን እንዲህ ሆነ፤ የይስሐቅ ባሪያዎች መጡ ስለ ማሱትም ጕድጓድ ነገሩት። ውኃ አገኘን አሉት።", "ስሙንም ሳባ ብሎ ጠራው፤ ስለዚህም የዚያች ከተማ ስም እስከ ዛሬ ድረስ ቤርሳቤህ ተብሎ ይጠራል።", "ዔሳውም የአርባ ዓመት ሰው በሆነ ጊዜ የኬጢያዊ የብኤሪን ልጅ ዮዲትን፥ የኬጢያዊ የኤሎንንም ልጅ ባሴማትን ሚስት አድርጎ አገባ፤", "እነርሱም ለይስሐቅና ለርብቃ የልብ ኀዘን ሆኑባቸው።"]},
  {"chapter": "27", "title": "", "verses": ["እንዲህም ሆነ፤ ይስሐቅ ባረጀ ጊዜ ዓይኖቹ እንዳያዩ ፈዘዙ፤ ታላቁን ልጁን ዔሳውን ጠርቶ። ልጄ ሆይ አለው፤ እርሱም። እነሆኝ አለ።", "አለ። እነሆ፥ እኔ አርጅቻለሁ፥ የምሞትበትንም ቀን አላውቅም፤", "አሁንም ዕቃህን፥ አፎትህንና ቀስትህን፥ ያዝ፥ ወደ ሜዳም ውጣ፥ አድንም አድንልኝ፤", "እኔ እንደምወደውም ጣፋጭ መብል አድርግልኝ፥ ነፍሴ ሳትሞት እንድትባርክህ እንድበላ አምጣልኝ።", "ይስሐቅም ለልጁ ለዔሳው ሲናገር ርብቃ ትሰማ ነበር፤ ዔሳውም አድኖ ያመጣ ዘንድ ወደ ሜዳ ሄደ።", "ርብቃም ልጇን ያዕቆብን እንዲህ ብላ ተናገረችው። እነሆ፥ አባትህ ወንድምህን ዔሳውን እንዲህ ሲለው ሰማሁ።", "አድነህ አምጣልኝ፥ እንድበላም ጣፋጭ መብል አድርግልኝ፥ ሳልሞትም በእግዚአብሔር ፊት እባርክሃለሁ።", "አሁንም ልጄ ሆይ፥ የማዝዝህን ቃሌን ስማ፤", "ወደ በጎች ሂድና ከዚያ ሁለት መልካም የፍየል ጠቦቶች አምጣልኝ፥ እኔም አባትህ እንደሚወደው ጣፋጭ መብል አድርጌ ለአባትህ አዘጋጃለሁ፤", "ነፍሱ ሳትሞት እንዲባርክህ እንዲበላ ለአባትህ ታገባለህ።", "ያዕቆብም እናቱን ርብቃን አላት። እነሆ፥ ወንድሜ ዔሳው ጠጕራም ሰው ነው፥ እኔ ግን ለስላሳ ሰው ነኝ፤", "ምናልባት አባቴ ቢዳስሰኝ በእርሱ ዘንድ እንደ አታላይ እሆናለሁ፤ በራሴም ላይ መርገምን አመጣለሁ እንጂ በረከትን አላገኝም።", "እናቱም አለችው። ልጄ ሆይ፥ መርገምህ በእኔ ላይ ይሁን፤ ብቻ ቃሌን ስማ፥ ሄደህም አምጣልኝ።", "ሄደም፥ ወሰደም፥ ለእናቱም አመጣላት፤ እናቱም አባቱ እንደሚወደው ጣፋጭ መብል አደረገች።", "ርብቃም በቤት የነበረውን የታላቁን ልጇን የዔሳውን የተመረጠውን ልብስ ወሰደች፥ ታናሹንም ልጇን ያዕቆብን አለበሰችው፤", "የፍየል ጠቦቶችንም ቁርበት በእጆቹና በለስላሳው አንገቱ ላይ አደረገች፤", "ያዘጋጀችውንም ጣፋጭ መብልና እንጀራ በልጇ በያዕቆብ እጅ ሰጠችው።", "ወደ አባቱም ገባና። አባቴ ሆይ አለ፤ እርሱም። እነሆኝ ልጄ፥ አንተ ማን ነህ? አለ።", "ያዕቆብም አባቱን አለው። እኔ የበኵር ልጅህ ዔሳው ነኝ፤ እንዳልኸኝ አደረግሁ፤ ተነሥተህ ተቀመጥ፥ ነፍስህም እንድትባርከኝ ከአደኔ ብላ።", "ይስሐቅም ልጁን። ልጄ ሆይ፥ እንዴት እንዲህ ፈጥነህ አገኘህ? አለው፤ እርሱም። አምላክህ እግዚአብሔር በመንገዴ ሰጠኝ አለ።", "ይስሐቅም ያዕቆብን። ልጄ ሆይ፥ አንተ ልጄ ዔሳው እንደ ሆንህ ወይም እንዳልሆንህ እንድዳስስህ ወደ እኔ ቅረብ አለው።", "ያዕቆብም ወደ አባቱ ወደ ይስሐቅ ቀረበ፥ ዳሰሰውም፤ እንዲህም አለ። ድምፅ የያዕቆብ ድምፅ ነው፥ እጆች ግን የዔሳው እጆች ናቸው።", "እጆቹ እንደ ወንድሙ እንደ ዔሳው እጆች ጠጕራም ነበሩና አላወቀውም፤ ባረከውም።", "አንተ ልጄ ዔሳው በእውነት ነህን? አለ፤ እርሱም። ነኝ አለ።", "አለ። ወደ እኔ አቅርበው፥ ነፍሴ ትባርክህ ዘንድ ከልጄ አደን ልብላ። አቀረበለትም፥ በላም፤ የወይን ጠጅም አመጣለት፥ ጠጣም።", "አባቱ ይስሐቅም። ልጄ ሆይ፥ ቅረብና ሳመኝ አለው።", "ቀረበም፥ ሳመውም፤ የልብሱንም ሽታ አሸተተ፥ ባረከውም እንዲህም አለ። እነሆ፥ የልጄ ሽታ እግዚአብሔር እንደ ባረከው እንደ እርሻ ሽታ ነው፤", "እግዚአብሔር ከሰማይ ጠል ከምድርም ስብ፥ ከእህልና ከወይን ጠጅም ብዛት ይስጥህ፤", "አሕዛብ ይገዙልህ፥ ወገኖችም ይስገዱልህ፤ ለወንድሞችህ ጌታ ሁን፥ የእናትህም ልጆች ይስገዱልህ፤ የሚረግሙህ ሁሉ ርጉማን ይሁኑ፥ የሚባርኩህም ሁሉ ቡሩካን ይሁኑ።", "ይስሐቅም ያዕቆብን መባረክ በፈጸመ ጊዜ፥ ያዕቆብም ከአባቱ ከይስሐቅ ፊት ገና ሲወጣ፥ ወንድሙ ዔሳው ከአደኑ መጣ።", "እርሱም ደግሞ ጣፋጭ መብል አዘጋጀ፥ ወደ አባቱም አገባው፥ አባቱንም። አባቴ ይነሣ፥ ነፍሱ እንድትባርከኝ ከልጁ አደን ይብላ አለው።", "አባቱ ይስሐቅም። አንተ ማን ነህ? አለው። እርሱም። የበኵር ልጅህ ዔሳው ነኝ አለ።", "ይስሐቅም እጅግ ታላቅ መንቀጥቀጥ ተንቀጠቀጠ እንዲህም አለ። እንግዲያስ ያ አድኖ አደን ያመጣልኝ ማን ነው? አንተ ሳትመጣ ከሁሉ በላሁ፥ ባረክሁትም፤ እርሱም በእውነት ቡሩክ ይሆናል።", "ዔሳውም የአባቱን ቃል በሰማ ጊዜ እጅግ መራራ በሆነ በታላቅ ድምፅ ጮኸ፥ አባቱንም። አባቴ ሆይ፥ እኔንም ደግሞ ባርከኝ አለው።", "እርሱም። ወንድምህ በተንኰል መጣ፥ በረከትህንም ወሰደ አለ።", "እርሱም። በውኑ ስሙ ያዕቆብ የተባለ ስለዚህ አይደለምን? ይኸው ሁለት ጊዜ አሰናከለኝ፤ ብኵርናዬን ወሰደ፥ አሁንም እነሆ በረከቴን ወሰደ አለ። እርሱም። ለእኔ በረከትን አላስቀረህልኝምን? አለ።", "ይስሐቅም መለሰ ዔሳውንም አለው። እነሆ፥ ለአንተ ጌታ አደረግሁት፥ ወንድሞቹንም ሁሉ ለእርሱ ባሪያዎች እንዲሆኑ ሰጠሁት፥ በእህልና በወይን ጠጅም ደገፍሁት፤ እንግዲህ ለአንተ፥ ልጄ ሆይ፥ ምን አደርጋለሁ?", "ዔሳውም አባቱን። አባቴ ሆይ፥ አንዲት ብቻ በረከት አለችን? አባቴ ሆይ፥ እኔንም ደግሞ ባርከኝ አለው፤ ዔሳውም ድምፁን አንሥቶ አለቀሰ።", "አባቱ ይስሐቅም መለሰ አለውም። እነሆ፥ ማደሪያህ ከምድር ስብ ከሰማይም ጠል በላይ ይሆናል፤", "በሰይፍህም ትኖራለህ፥ ለወንድምህም ትገዛለህ፤ እንዲህም ይሆናል፤ ስታምፅ ቀንበሩን ከአንገትህ ላይ ትሰብራለህ።", "ዔሳውም አባቱ ስለ ባረከው በረከት ያዕቆብን ጠላው፤ ዔሳውም በልቡ አለ። ለአባቴ የኀዘን ቀን ቀርቦአል፥ ከዚያም በኋላ ወንድሜን ያዕቆብን እገድለዋለሁ።", "ለርብቃም የታላቁ ልጇ የዔሳው ነገር ተነገራት፤ እርስዋም ልካ ታናሹን ልጇን ያዕቆብን አስጠራችው እንዲህም አለችው። እነሆ፥ ወንድምህ ዔሳው አንተን በመግደል ቂሙን ሊወጣ ያሳስበዋል።", "አሁንም ልጄ ሆይ፥ ቃሌን ስማ፤ ተነሥተህ ወደ ካራን ወደ ወንድሜ ወደ ላባ ሽሽ፤", "የወንድምህ ቍጣ እስኪበርድ ድረስ ጥቂት ቀን በእርሱ ዘንድ ተቀመጥ፤", "የወንድምህ ቁጣ ከአንተ እስኪመለስ ድረስ፥ በእርሱም ያደረግኸውን እስኪረሳ ድረስ፤ እኔ ልኬ ከዚያ አስመጣሃለሁ፤ በአንድ ቀን በሁለታችሁ ላይ ለምን እመክናለሁ?", "ርብቃም ይስሐቅን አለችው። ከኬጢ ልጆች ሴቶች የተነሣ ሕይወቴን ጠላኋት፤ ያዕቆብም ከእነዚህ ከዚህች ምድር ሴቶች ልጆች እንደ እነዚህ ያሉትን የኬጢን ሴት ልጅ ቢያገባ፥ በሕይወት መኖር ለእኔ ምን ይጠቅመኛል?"]},
  {"chapter": "28", "title": "", "verses": ["ይስሐቅም ያዕቆብን ጠራና ባረከው፥ አዘዘውም እንዲህም አለው። ከከነዓን ሴቶች ልጆች ሚስትን አታግባ፤", "ተነሥተህ ወደ ሁለቱ ወንዞች መካከል ምድር ወደ እናትህ አባት ወደ ባቱኤል ቤት ሂድ፥ ከዚያም ከእናትህ ወንድም ከላባ ሴቶች ልጆች ሚስትን ለአንተ ውሰድ።", "ሁሉን የሚችል አምላክ ይባርክህ፥ ያፍራህም፥ ያብዛህም፥ የብዙ አሕዛብም ማኅበር ሁን፤", "እግዚአብሔር ለአብርሃም የሰጣትን በእንግድነት የምትኖርባትን ምድር ትወርስ ዘንድ፥ ለአንተና ከአንተ ጋር ለዘርህ የአብርሃምን በረከት ይስጥህ።", "ይስሐቅም ያዕቆብን አሰናበተው፥ እርሱም ወደ ሁለቱ ወንዞች መካከል ምድር ወደ ሶርያዊው ወደ ባቱኤል ልጅ ወደ ላባ ዘንድ ሄደ፤ እርሱም የያዕቆብና የዔሳው እናት የርብቃ ወንድም ነበረ።", "ዔሳውም ይስሐቅ ያዕቆብን እንደ ባረከው፥ ከዚያም ሚስትን ያገባ ዘንድ ወደ ሁለቱ ወንዞች መካከል ምድር እንዳሰናበተው፥ በባረከውም ጊዜ። ከከነዓን ሴቶች ልጆች ሚስትን አታግባ ብሎ እንዳዘዘው፥", "ያዕቆብም የአባቱንና የእናቱን ቃል ሰምቶ ወደ ሁለቱ ወንዞች መካከል ምድር እንደ ሄደ አየ፤", "ዔሳውም የከነዓን ሴቶች ልጆች በአባቱ በይስሐቅ ዘንድ ክፉዎች እንደ ሆኑ አየ፤", "ዔሳውም ወደ እስማኤል ሄደ፥ ካገባቸውም ሚስቶች ሌላ የአብርሃም ልጅ የእስማኤልን ልጅ የነባዮትን እኅት መሔሌትን አገባ።", "ያዕቆብም ከቤርሳቤህ ወጥቶ ወደ ካራን ሄደ።", "ወደ አንድ ስፍራም ደረሰ፥ ፀሐይም ጠልቃ ነበርና በዚያ አደረ፤ በዚያም ስፍራ ድንጋይ አነሣ፥ ከራሱም በታች ተንተርሶ በዚያ ስፍራ ተኛ።", "ሕልምም አለመ፤ እነሆም፥ መሰላል በምድር ላይ ተተክሎ፥ ራሱም ወደ ሰማይ ደርሶ፥ የእግዚአብሔርም መላእክት ይወጡበት ይወርዱበት ነበር።", "እነሆም፥ እግዚአብሔር በላይ ቆሞበት ነበር፥ እንዲህም አለ። የአባትህ የአብርሃም አምላክ የይስሐቅም አምላክ እግዚአብሔር እኔ ነኝ፤ ይህችን አንተ የተኛህባትን ምድር ለአንተም ለዘርህም እሰጣለሁ፤", "ዘርህም እንደ ምድር አሸዋ ይሆናል፤ ወደ ምዕራብና ወደ ምሥራቅ ወደ ሰሜንና ወደ ደቡብ ትሰራጫለህ፤ የምድርም አሕዛብ ሁሉ በአንተ በዘርህም ይባረካሉ።", "እነሆም፥ እኔ ከአንተ ጋር ነኝ፥ በምትሄድበትም መንገድ ሁሉ እጠብቅሃለሁ፥ ወደዚችም ምድር እመልስሃለሁ፤ የነገርሁህን ሁሉ እስካደርግልህ ድረስ አልተውህምና።", "ያዕቆብም ከእንቅልፉ ነቅቶ። በእውነት እግዚአብሔር በዚህ ስፍራ አለ፤ እኔ ግን አላወቅሁም ነበር አለ።", "ፈርቶም። ይህ ስፍራ እንዴት ያስፈራ፤ ይህ ስፍራ የእግዚአብሔር ቤት እንጂ ሌላ አይደለም፤ ይህም የሰማይ ደጅ ነው አለ።", "ያዕቆብም በማለዳ ተነሣ፥ ተንተርሶት የነበረውንም ድንጋይ ወስዶ ሐውልት አድርጎ አቆመው፥ በላዩም ዘይትን አፈሰሰበት።", "ያዕቆብም የዚያን ስፍራ ስም ቤቴል ብሎ ጠራው፤ የዚያች ከተማ ስም ግን አስቀድሞ ሎዛ ነበረ።", "ያዕቆብም እንዲህ ብሎ ስእለት ተሳለ። እግዚአብሔር ከእኔ ጋር ቢሆን፥ በምሄድባትም በዚህች መንገድ ቢጠብቀኝ፥ የምበላውም እንጀራ የምለብሰውም ልብስ ቢሰጠኝ፥", "ወደ አባቴም ቤት በሰላም ብመለስ፥ እግዚአብሔር አምላኬ ይሆንልኛል፤", "ሐውልት አድርጌ ያቆምሁት ይህ ድንጋይም የእግዚአብሔር ቤት ይሆናል፤ ከሰጠኸኝም ሁሉ ለእኔ ለአንተ ከአሥር አንድ እሰጥሃለሁ።"]},
  {"chapter": "29", "title": "", "verses": ["ያዕቆብም መንገዱን ቀጠለ፥ ወደ ምሥራቅ ሰዎችም ምድር መጣ።", "ተመለከተም፥ እነሆም፥ በሜዳ ላይ የውኃ ጕድጓድ አየ፤ በዚያም አጠገብ የተኙ ሦስት የመንጋ መንጎች ነበሩ፥ ከዚያ ጕድጓድ መንጎቹን ያጠጡ ነበርና፤ በጕድጓዱም አፍ ላይ ታላቅ ድንጋይ ነበረ።", "መንጎቹም ሁሉ ወደዚያ ይሰበሰቡ ነበር፥ ድንጋዩንም ከጕድጓዱ አፍ ያንከባልሉ ነበር፥ በጎቹንም ያጠጡ ነበር፤ ድንጋዩንም ወደ ስፍራው ወደ ጕድጓዱ አፍ ይመልሱት ነበር።", "ያዕቆብም። ወንድሞቼ ሆይ፥ ከወዴት ናችሁ? አላቸው። እነርሱም። እኛ ከካራን ነን አሉት።", "እርሱም። የናኮርን ልጅ ላባን ታውቁታላችሁን? አላቸው። እነርሱም። እናውቀዋለን አሉት።", "እርሱም። ደኅና ነውን? አላቸው። እነርሱም። ደኅና ነው፤ እነሆም ልጁ ራሔል ከበጎች ጋር ትመጣለች አሉት።", "እርሱም። እነሆ ገና ቀኑ ብዙ ነው፥ ከብቶቹ የሚሰበሰቡበት ጊዜ አልደረሰም፤ በጎቹን አጠጡና ሂዱ አሰማሩ አላቸው።", "እነርሱም። መንጎቹ ሁሉ እስኪሰበሰቡ ድረስ፥ ድንጋዩንም ከጕድጓዱ አፍ እስኪያነከባልሉ ድረስ፥ አንችልም፤ ከዚያም በኋላ በጎቹን እናጠጣለን አሉት።", "እርሱም ገና ከእነርሱ ጋር ሲነጋገር ራሔል ከአባትዋ በጎች ጋር መጣች፥ ጠባቂ ነበረችና።", "እንዲህም ሆነ፤ ያዕቆብ የእናቱን ወንድም የላባን ልጅ ራሔልንና የእናቱን ወንድም የላባን በጎች ባየ ጊዜ፥ ያዕቆብ ቀረበ ድንጋዩንም ከጕድጓዱ አፍ አንከባለለ፥ የእናቱንም ወንድም የላባን በጎች አጠጣ።", "ያዕቆብም ራሔልን ሳማት፥ ቃሉንም አንሥቶ አለቀሰ።", "ያዕቆብም እርሱ የአባትዋ ዘመድ የርብቃም ልጅ እንደ ሆነ ለራሔል ነገራት፤ እርስዋም ሮጣ ለአባትዋ ነገረች።", "ላባም የእኅቱን ልጅ የያዕቆብን ወሬ በሰማ ጊዜ ሊቀበለው ሮጠ፥ አቀፈውም ሳመውም፥ ወደ ቤቱም አገባው፤ እርሱም ያደረገውን ነገር ሁሉ ለላባ ነገረው።", "ላባም። አንተ በእውነት አጥንቴና ሥጋዬ ነህ አለው፤ በአንድ ወር ሙሉ በእርሱ ዘንድ ተቀመጠ።", "ላባም ያዕቆብን። አንተ ዘመዴ ስለ ሆንህ በከንቱ ልታገለግለኝ ይገባልን? ደመወዝህ ምን እንዲሆንልህ ንገረኝ አለው።", "ለላባም ሁለት ሴቶች ልጆች ነበሩት፤ የታላቂቱ ስም ሊያ፥ የታናሺቱም ስም ራሔል ነበረ።", "የሊያም ዓይኖች ፈዛዞች ነበሩ፤ ራሔል ግን ውብ ነበረች ፊቷም ያማረ ነበረ።", "ያዕቆብም ራሔልን ወደዳት፤ እንዲህም አለ። ስለ ታናሺቱ ልጅህ ስለ ራሔል ሰባት ዓመት አገለግልሃለሁ።", "ላባም። ለሌላ ሰው ከምሰጣት ለአንተ እሰጣት ዘንድ ይሻላል፤ በእኔ ዘንድ ተቀመጥ አለ።", "ያዕቆብም ስለ ራሔል ሰባት ዓመት አገለገለ፤ እርሱንም ስለ ወደዳት እንደ ጥቂት ቀን ሆነለት።", "ያዕቆብም ላባን። ቀኔ ተፈጽሞአልና ወደ እርስዋ እንድገባ ሚስቴን ስጠኝ አለው።", "ላባም የዚያን ስፍራ ሰዎች ሁሉ ሰበሰበ፥ ግብዣም አደረገ።", "በመሸም ጊዜ ልጁን ሊያን ወሰደ፥ ወደ እርሱም አገባት፤ እርሱም ወደ እርስዋ ገባ።", "ላባም ለልጁ ለሊያ ባሪያይቱን ዘለፋን ባሪያ እንድትሆናት ሰጣት።", "በነጋውም እነሆ ሊያ ነበረች፤ ላባንም። ይህ ያደረግህብኝ ምንድር ነው? ስለ ራሔል ያገለገልሁህ አይደለምን? ስለ ምን አታለልኸኝ? አለው።", "ላባም አለ። በአገራችን ከታላቂቱ በፊት ታናሺቱን መዳር ልማድ አይደለም።", "የዚችን ሳምንት ፈጽም፥ እርስዋንም ደግሞ በሌላ ሰባት ዓመት ስለ ምታገለግለኝ አገልግሎት እሰጥሃለሁ።", "ያዕቆብም እንዲሁ አደረገ፥ የዚችንም ሳምንት ፈጸመ፤ ልጁን ራሔልንም ሚስት ትሆነው ዘንድ ሰጠው።", "ላባም ለልጁ ለራሔል ባሪያይቱን ባላን ባሪያ እንድትሆናት ሰጣት።", "ወደ ራሔልም ደግሞ ገባ፥ ሊያን ከወደዳት ይልቅ ራሔልን ወደዳት፤ ደግሞም ሌላ ሰባት ዓመት አገለገለው።", "እግዚአብሔርም ሊያ እንደ ተጠላች ባየ ጊዜ ማኅፀንዋን ከፈተላት፤ ራሔል ግን መካን ነበረች።", "ሊያም ፀነሰች፥ ወንድ ልጅንም ወለደች፤ ስሙንም ሮቤል ብላ ጠራችው። እግዚአብሔር መቸገሬን አይቶልኛልና፥ አሁን ባሌ ይወደኛል ስትል ስሙን ሮቤል አለችው።", "ደግሞም ፀነሰች፥ ወንድ ልጅንም ወለደች፤ እርስዋም። እኔ እንደ ተጠላሁ እግዚአብሔር ሰምቶ ይህን ደግሞ ለእኔ ሰጠኝ አለች፤ ስሙንም ስምዖን ብላ ጠራችው።", "ደግሞም ፀነሰች፥ ወንድ ልጅንም ወለደች፤ እርስዋም። ሦስት ወንዶች ልጆች ወልጄለታለሁና አሁን በዚህ ጊዜ ባሌ ከእኔ ጋር ይጣበቃል አለች፤ ስለዚህም ስሙ ሌዊ ተባለ።", "ደግሞም ፀነሰች፥ ወንድ ልጅንም ወለደች፤ እርስዋም። አሁን እግዚአብሔርን አመሰግናለሁ አለች፤ ስለዚህም ስሙን ይሁዳ ብላ ጠራችው፤ መውለድንም አቆመች።"]},
  {"chapter": "30", "title": "", "verses": ["ራሔልም ለያዕቆብ ልጆችን እንዳልወለደች ባየች ጊዜ በወንድምዋ ቀናች፤ ያዕቆብንም። ልጆችን ስጠኝ፥ አለዚያ ግን እሞታለሁ አለችው።", "የያዕቆብም ቍጣ በራሔል ላይ ነደደ፥ እንዲህም አለ። የማኅፀንሽን ፍሬ የከለከለሽን እግዚአብሔርን በውኑ እኔ እመስለዋለሁን?", "እርስዋም አለችው። እነሆ ባሪያዬ ባላ፤ ወደ እርስዋ ግባ፥ በእኔ ጭን ላይ ትውለድ፥ እኔም ደግሞ በእርስዋ እታነጻለሁ።", "ባሪያዋንም ባላን ሚስት ትሆነው ዘንድ ሰጠችው፥ ያዕቆብም ወደ እርስዋ ገባ።", "ባላም ፀነሰች፥ ለያዕቆብም ወንድ ልጅ ወለደችለት።", "ራሔልም። እግዚአብሔር ፈረደልኝ፥ ድምፄንም ደግሞ ሰማኝ፥ ወንድ ልጅንም ሰጠኝ አለች፤ ስለዚህም ስሙን ዳን ብላ ጠራችው።", "የራሔል ባሪያ ባላም ደግሞ ፀነሰች፥ ለያዕቆብም ሁለተኛ ወንድ ልጅ ወለደችለት።", "ራሔልም። ከእኅቴ ጋር ታላቅ ትግል ታገልሁ አሸነፍሁም አለች፤ ስሙንም ንፍታሌም ብላ ጠራችው።", "ሊያም መውለድ እንዳቆመች ባየች ጊዜ ባሪያዋን ዘለፋን ወሰደች፥ ለያዕቆብም ሚስት ትሆነው ዘንድ ሰጠችው።", "የሊያ ባሪያ ዘለፋም ለያዕቆብ ወንድ ልጅ ወለደችለት።", "ሊያም። በረከት መጣች አለች፤ ስሙንም ጋድ ብላ ጠራችው።", "የሊያ ባሪያ ዘለፋም ለያዕቆብ ሁለተኛ ወንድ ልጅ ወለደችለት።", "ሊያም። ደስ አለኝ፥ ሴቶች ያስመሰግኑኛልና አለች፤ ስሙንም አሴር ብላ ጠራችው።", "ሮቤልም በስንዴ መከር ወራት ሄደ፥ በሜዳም እንኮይ አገኘ፥ ወደ እናቱም ወደ ሊያ አመጣው። ራሔልም ሊያን። ከልጅሽ እንኮይ እንድትሰጪኝ እለምንሻለሁ አለቻት።", "እርስዋም። ባሌን መውሰድሽ ጥቂት ነውን? የልጄንም ደግሞ እንኮይ ትወስጃለሽን? አለቻት። ራሔልም። ስለዚህ ስለ ልጅሽ እንኮይ ዛሬ ሌሊት ከአንቺ ጋር ይተኛል አለች።", "ያዕቆብም በማታ ከሜዳ ሲመጣ ሊያ ልትቀበለው ወጣች፥ እንዲህም አለች። በልጄ እንኮይ በእውነት ተከራይቼሃለሁና ወደ እኔ ግባ። በዚያችም ሌሊት ከእርስዋ ጋር ተኛ።", "እግዚአብሔርም የሊያን ልመና ሰማ፥ ፀነሰችም፥ ለያዕቆብም አምስተኛ ወንድ ልጅ ወለደችለት።", "ሊያም። ባሪያዬን ለባሌ ስለ ሰጠሁ እግዚአብሔር ዋጋዬን ሰጠኝ አለች፤ ስሙንም ይሳኮር ብላ ጠራችው።", "ሊያም ደግሞ ፀነሰች፥ ለያዕቆብም ስድስተኛ ወንድ ልጅ ወለደችለት።", "ሊያም። እግዚአብሔር መልካም ስጦታ ሰጠኝ፤ ስድስት ወንዶች ልጆች ወልጄለታለሁና አሁን ባሌ ከእኔ ጋር ይኖራል አለች፤ ስሙንም ዛብሎን ብላ ጠራችው።", "ከዚህም በኋላ ሴት ልጅ ወለደች፥ ስምዋንም ዲና ብላ ጠራችው።", "እግዚአብሔርም ራሔልን አሰበ፥ እግዚአብሔርም ሰማት፥ ማኅፀንዋንም ከፈተላት።", "ፀነሰችም፥ ወንድ ልጅንም ወለደች፤ እንዲህም አለች። እግዚአብሔር ስድቤን አስወገደልኝ።", "ስሙንም። እግዚአብሔር ሌላ ልጅ ይጨምርልኝ ስትል ዮሴፍ ብላ ጠራችው።", "እንዲህም ሆነ፤ ራሔል ዮሴፍን ከወለደች በኋላ ያዕቆብ ላባን አለው። ወደ ስፍራዬና ወደ አገሬ እሄድ ዘንድ አሰናብተኝ።", "ያገለገልሁህባቸውን ሚስቶቼንና ልጆቼን ስጠኝና ልሂድ፤ ያገለገልሁህን አገልግሎቴን አንተ ታውቃለህና።", "ላባም አለው። በፊትህ ሞገስ አግኝቼ እንደ ሆነ እባክህ ተቀመጥ፤ እግዚአብሔር በአንተ ምክንያት እንደ ባረከኝ ተረድቼአለሁና።", "ደግሞም። ደመወዝህን ንገረኝ፥ እሰጥሃለሁ አለ።", "እርሱም አለው። እኔ እንዴት እንዳገለገልሁህ፥ ከብቶችህም በእኔ ዘንድ እንዴት እንደ ሆኑ አንተ ታውቃለህ።", "እኔ ከመምጣቴ በፊት የነበረህ ጥቂት ነበረ፥ አሁን ግን እጅግ በዝቶአል፤ እኔ በመጣሁበት ጊዜ እግዚአብሔር ባረከህ፤ አሁንም እኔ ደግሞ ለቤቴ የማደርገው መቼ ነው?", "እርሱም። ምን ልስጥህ? አለ። ያዕቆብም አለ። ምንም አትስጠኝ፤ ይህን ነገር ብታደርግልኝ እንደ ገና መንጋህን እጠብቃለሁ አሰማራለሁም።", "ዛሬ በመንጎችህ ሁሉ መካከል አልፋለሁ፥ ከበጎቹም ዥንጉርጉሩንና ነጠብጣብ ያለበትን፥ ከጠቦቶቹም ጥቁር የሆነውን፥ ከፍየሎቹም ነጠብጣብና ዥንጉርጉር ያለበትን ሁሉ ለይ፤ ደመወዜም ያ ይሁን።", "ጽድቄም ነገ ስትመጣ ትመሰክርልኛለች፤ ደመወዜም በፊትህ በሚሆንበት ጊዜ፥ ከፍየሎቹ ነጠብጣብና ዥንጉርጉር የሌለበት፥ ከጠቦቶቹም ጥቁር ያልሆነው፥ ሁሉ ቢገኝ እንደ ተሰረቀ ይቈጠርብኝ።", "ላባም። መልካም ነው፥ እንደ ቃልህ ይሁን አለ።", "በዚያም ቀን ሽመልመሌዎችንና ዥንጉርጉሮቹን አውራ ፍየሎች፥ ነጠብጣብና ዥንጉርጉር ያለባቸውን እንስቶች ፍየሎች ሁሉ፥ ነጭ ያለበትን ሁሉ፥ ከጠቦቶቹም ጥቁሮቹን ሁሉ ለየ፥ በልጆቹም እጅ ሰጣቸው።", "በእርሱና በያዕቆብ መካከል የሦስት ቀን መንገድ አደረገ፤ ያዕቆብም የቀሩትን የላባን በጎች አሰማራ።", "ያዕቆብም ከልቡጥና ከለውዝ ከዶልብም ዛፍ የለመለሙ በትሮችን ወሰደ፤ ነጩም እንጨት እስኪታይ ድረስ በበትሮቹ ላይ ላጠ፥ ነጭ ሽመልመሌም አደረጋቸው።", "የላጣቸውንም በትሮች በጎቹ ውኃ ሊጠጡ በሚመጡበት በውኃው ገንዳዎችና ቦዮች ውስጥ በበጎቹ ፊት አኖራቸው፤ በጎቹም ውኃ ሊጠጡ በመጡ ጊዜ ይጐመጁ ነበር።", "በጎቹም በበትሮቹ ፊት ተጐመጁ፤ በጎቹም ሽመልመሌ፥ ነጠብጣብና ዥንጉርጉር ያለበትን ወለዱ።", "ያዕቆብም ጠቦቶቹን ለየ፥ የበጎቹንም ፊት በላባ መንጋ ወደ ነበሩት ወደ ሽመልመሌዎቹና ወደ ጥቁሮቹ ሁሉ አደረገ፤ መንጎቹንም ለብቻቸው አኖረ፥ ከላባ በጎች ጋር አልቀላቀላቸውም።", "ብርቱዎቹም በጎች በተጐመጁ ጊዜ በጎቹ በበትሮቹ ፊት እንዲጐመጁ ያዕቆብ በውኃው ቦዮች ውስጥ በበጎቹ ዓይን ፊት በትሮቹን ያኖር ነበር።", "በጎቹ ግን ደካሞች በሆኑ ጊዜ አያኖራቸውም ነበር፤ ደካሞቹ የላባ ሆኑ፥ ብርቱዎቹም የያዕቆብ ሆኑ።", "ሰውዬውም እጅግ በጣም ባለጠጋ ሆነ፤ ብዙ መንጎች፥ ሴቶችና ወንዶች ባሪያዎች፥ ግመሎችና አህዮችም ሆኑለት።"]}
]

